insert into public.news ("id", "title", "slug", "excerpt", "content", "unit", "category", "author", "publish_date", "image_url", "is_featured", "views") values ('news-2', 'Siswa SMP Al-Huda Raih Juara 1 Olimpiade Sains Matematika Tingkat Kabupaten Sidoarjo', 'siswa-smp-al-huda-raih-juara-1-osn-sidoarjo', 'Prestasi membanggakan ditorehkan ananda Muhammad Faris Al-Fatih dalam ajang kompetisi sains pelajar SMP se-Kabupaten Sidoarjo.', 'Kabar membanggakan datang dari SMP Al-Huda Krian. Salah satu siswa kelas VIII, Muhammad Faris Al-Fatih, sukses meraih medali emas (Juara 1) pada ajang Olimpiade Sains Matematika tingkat SMP se-Kabupaten Sidoarjo yang diadakan oleh MGMP Matematika.
insert into public.news ("id", "title", "slug", "excerpt", "content", "unit", "category", "author", "publish_date", "image_url", "is_featured", "views") values ('news-3', 'Wisuda Tahfidz Al-Qur''an Juz 30 dan Juz 1-5 Pondok Pesantren Al-Huda Berlangsung Khidmat', 'wisuda-tahfidz-al-quran-pondok-pesantren-al-huda', 'Sebanyak 65 santriwan dan santriwati Pondok Pesantren Al-Huda diwisuda setelah menuntaskan hafalan dengan predikat Jayyid Jiddan dan Mumtaz.', 'Pondok Pesantren Al-Huda Tundungan menggelar prosesi Wisuda Tahfidzul Qur''an Angkatan ke-XII di Aula Utama Pesantren. Acara ini dihadiri oleh jajaran Pengasuh, Dewan Masyayikh, serta para wali santri yang hadir dengan penuh haru dan bangga.
insert into public.news ("id", "title", "slug", "excerpt", "content", "unit", "category", "author", "publish_date", "image_url", "views") values ('news-4', 'Pengajian Akbar dan Haul Pendiri Yayasan Al-Huda Dihadiri Ribuan Jamaah se-Krian', 'pengajian-akbar-dan-haul-pendiri-yayasan-al-huda', 'Rangkaian peringatan Haul Masyayikh dan pengajian umum di halaman utama yayasan berlangsung penuh berkah dan kekeluargaan.', 'Ribuan alumni, wali santri, dan masyarakat sekitar Krian memadati komplek Yayasan Al-Huda Tundungan dalam rangka Haul Pendiri Yayasan dan Pengajian Akbar. Acara ini diisi tausiyah kebangsaan dan keislaman yang menekankan persatuan ummat dan pentingnya pendidikan berkarakter islami.', 'yayasan', 'Kegiatan', 'Panitia Haul', '2026-07-15', 'https://images.unsplash.com/photo-1542810634-71277d95dcbb?q=80&w=800&auto=format&fit=crop', 290) on conflict (id) do nothing;
insert into public.news ("id", "title", "slug", "excerpt", "content", "unit", "category", "author", "publish_date", "image_url", "views") values ('news-5', 'Penerapan Pembelajaran Interaktif Berbasis Digital Smart Classroom di SMP Al-Huda', 'pembelajaran-digital-smart-classroom-smp-al-huda', 'Untuk menunjang Kurikulum Merdeka, seluruh ruang kelas SMP Al-Huda kini dilengkapi perangkat multimedia interaktif dan akses perpustakaan digital.', 'SMP Al-Huda terus berinovasi dalam memajukan mutu pembelajaran. Mulai semester ini, fasilitas smart board dan jaringan edukasi intranet telah diimplementasikan di seluruh kelas untuk memudahkan guru menyampaikan materi secara visual dan kolaboratif.', 'smp', 'Akademik', 'Kurikulum SMP', '2026-07-02', 'https://images.unsplash.com/photo-1580582932707-520aed937b7b?q=80&w=800&auto=format&fit=crop', 215) on conflict (id) do nothing;
insert into public.news ("id", "title", "slug", "excerpt", "content", "unit", "category", "author", "publish_date", "image_url", "views") values ('news-6', 'Kajian Rutin Kitab Kuning Fathul Qorib dan Ta''lim Muta''allim Bersama Dewan Pengasuh', 'kajian-rutin-kitab-kuning-pesantren-al-huda', 'Santri mukim mendalami fiqih dasar dan adab penuntut ilmu setiap ba''da maghrib dan subuh dengan metode bandongan dan sorogan.', 'Pondok Pesantren Al-Huda tetap istiqomah mempertahankan tradisi keilmuan pesantren salafiyah yang dipadukan dengan manajemen modern. Kajian kitab Ta''limul Muta''allim menjadi pondasi pembentukan adab dan akhlaq santri sebelum menyerap ilmu-ilmu lainnya.', 'pondok', 'Kajian', 'Pengurus Asrama', '2026-06-20', 'https://images.unsplash.com/photo-1584551246679-0daf3d275d0f?q=80&w=800&auto=format&fit=crop', 340) on conflict (id) do nothing;
